type RetryContext = {
    error: unknown;
    attempt: number;
    maxAttempts: number;
    streaming: boolean;
    turn?: number | undefined;
};
type RetryOptions = {
    maxAttempts?: number | undefined;
    initialDelayMs?: number | undefined;
    maxDelayMs?: number | undefined;
    shouldRetry?: ((context: RetryContext) => boolean) | undefined;
};
type RetrySetting = RetryOptions | false;

export type { RetryContext as R, RetryOptions as a, RetrySetting as b };
